function cur(obj) {
  let d = Date.UTC(obj.year, obj.month - 1, obj.day, obj.hour||0, obj.minute||0, obj.second||0, obj.millisecond||0);
  if (obj.year < 100 && obj.year >= 0) {
    d = new Date(d);
    d.setUTCFullYear(d.getUTCFullYear() - 1900);
  }
  return +d;
}
// candidate fix from upstream luxon
function fixed(obj) {
  let d = Date.UTC(obj.year, obj.month - 1, obj.day, obj.hour||0, obj.minute||0, obj.second||0, obj.millisecond||0);
  if (obj.year < 100 && obj.year >= 0) {
    d = new Date(d);
    d.setUTCFullYear(obj.year, obj.month - 1, obj.day);
  }
  return +d;
}
// independent reference: build from epoch and set full year explicitly
function ref(obj) {
  const d = new Date(0);
  d.setUTCFullYear(obj.year, obj.month - 1, obj.day);
  d.setUTCHours(obj.hour||0, obj.minute||0, obj.second||0, obj.millisecond||0);
  return +d;
}
